import { useState, useEffect, useContext } from 'react';
import Styled from '../styled/Navi.style';
import { SetViewContext, SetViewContact } from '../App';

const Navi = () => {
    const { viewStore, setViewStore } = useContext(SetViewContext);
    const { viewContact, setViewContact } = useContext(SetViewContact);

    return (
        <Styled.Navi id="navi">
            <h1>최순철의 Portfolio</h1>
            <ul>
                <li
                    className="profile"
                    onClick={() => {
                        setViewStore('Profile');
                    }}
                >
                    NaN . .
                    <img src="./assets/images/hand-with-pen.png" alt="" />
                </li>
                <li
                    className="skill"
                    onClick={() => {
                        setViewStore('Skill');
                    }}
                >
                    스킬
                    <img src="./assets/images/explosion.png" alt="" />
                </li>
                <li
                    className="career"
                    onClick={() => {
                        setViewStore('Career');
                    }}
                >
                    경력
                    <img src="./assets/images/pokemon.png" alt="" />
                </li>
                <li
                    className="project"
                    onClick={() => {
                        setViewStore('Project');
                    }}
                >
                    개인 프로젝트
                </li>
                <li
                    className="contact"
                    onClick={() => {
                        setViewContact(true);
                    }}
                >
                    연락처
                </li>
            </ul>
        </Styled.Navi>
    );
};
export default Navi;
