import Styled from 'styled-components';
const borderColor = '#4cd5b5';
const style = {
  Profile: Styled.div`
        background: url('./assets/images/img_csc03.png') no-repeat 550px -97px;
        background-size: 324px auto;
        font-size: 25px;
        text-align: left;
        line-height: 1.6;
        word-break: keep-all;

        .txt_dev {
            font-family: 'CookieRun-Regular';
            letter-spacing: -1px;
            &.green {
                text-shadow:  #181818 1px 1px 1px;
                color: #79ffde;
            }
            &.red {
                color: rgb(255 87 87);
                text-shadow: #421313 1px 1px 1px;
            }
            &.navy {
                color: rgb(84 151 225);
                text-shadow: rgb(50 22 255) 1px 1px 1px;
            }
            &.purple {
                color: rgb(249 110 206);
                text-shadow: rgb(129 36 153) 1px 1px 1px;
            }
        }
        h2 {
            margin:30px 0;
            font-size: 40px;
        }
        h3 {
            margin-bottom: 20px;
            font-size: 30px;
        }
        p {
            margin-top: 20px;
        }
        .introduction{
            padding-bottom: 60px;
            border-bottom: 2px solid ${borderColor};
            h2 {
                position: relative;
                img {
                    position: absolute;
                    top: -5px;
                    left: 131px;
                    width: 44px;
                    transform: rotate(7deg);
                }
            }
            .date{
                padding-right: 70px;
                margin-top: 40px;
                text-align: right;
            }
        }
        .skills{
            h2 {
                margin-bottom: 20px;
                img {
                    width: 40px;
                    margin: -14px 0 0px 17px;
                }
            }
            & > div {
                padding-bottom: 30px;
                border-bottom: 2px solid ${borderColor};
                & + div {
                    h3 {
                        margin-top: 30px;
                    }
                }
            }
            ul {
                margin-bottom: 40px;
                li {
                    display: inline-block;
                    & + li {
                        margin-left: 16px;
                    }
                    img {
                        width: 100px;
                    }
                    &.size{
                        img {
                            width: 80px;
                        }
                    }
                }
            }
            ol {
                padding-left: 20px;
                margin: 30px 0;
                font-size: 20px;
                font-weight: 600;
                li {
                    & + li {
                        margin-top: 4px;
                    }
                }
            }
        }
        .plan {
            padding-bottom: 30px;
            border-bottom: 2px solid ${borderColor};
            h2 {
                img {                
                    width: 60px;
                    margin: -23px 0px 0px 7px;
                }
            }
            p {
                img {
                    width: 40px;
                    margin: -4px 0 0 2px;
                }
            }
        }
    `,
};

export default style;
