import Styled from "styled-components";
const maxWidth = `1300px`;
const borderColor = "#4cd5b5";
const style = {
  Project: Styled.div`
        text-align: left;
        h2 {
            margin:30px 0;
            font-size: 40px;
            img {
                width: 46px;
                margin: -16px 0px 0px 14px;
            }
        }
        .txt_project{
            margin-bottom: 20px;
            padding-bottom: 20px;
            border-bottom: 2px solid ${borderColor};
            font-size: 24px;
        }
        ul {
            li {
                margin-bottom: 30px;
                dt {
                    margin-bottom: 20px;
                    font-size: 26px;
                    font-weight: 400;
                }
                dd {
                    display: flex;
                    justify-content: center;
                    margin-bottom: 10px;
                    font-size: 22px;
                    font-weight: 600;
                    .github{
                        width: 40px;
                        cursor: pointer;
                    }
                    .card {
                        width: 100px;
                        & + img {
                            margin-left: 10px;
                        }
                    }
                    span {
                        &.green {
                            color: rgb(17 112 30);
                        }
                        &.red {
                            color: rgb(203 82 82);
                        }
                        &.navy {
                            color: rgb(69 124 185);
                        }
                        &.purple {
                            color: rgb(217 79 174);
                        }
                    }
                }
                .img {
                    padding: 20px 0;
                    border-bottom: 2px solid ${borderColor};
                    text-align: center;
                    img {
                        width: 100%;
                        max-width: 800px;
                        border-radius: 10px;
                        &.w_auto {
                            width: auto;
                        }
                        & + img {
                            margin-top: 20px;
                        }
                    }
                    &.chu {
                        border-bottom: 0 none;
                    }
                    &.cards {
                        img {                        
                            width: 100px;
                            margin-bottom: 40px;
                        }
                    }
                }
                .poker{
                  margin-top: 20px;
                  img{
                    border-radius: 100%;
                  }
                }
            }
        }
        /* .masonry_grid {
            display: flex;
            width: auto;
            padding: 0 30px;
            max-width: ${maxWidth};
            .card {
                background: #fff;
                border: 1px solid rgb(195 195 195);
                border-radius: 10px;
                img {
                    width: 100%;
                    border-radius: 10px;
                }
            }
            .masonry_grid_column {
                padding:0 10px;
                background-clip: padding-box;
                & > div {
                    margin-bottom: 6px;
                    box-shadow: rgba(15, 15, 15, 0.1) 0px 1px 4px;
                }
            }
        } */
    `,
};

export default style;
