import Styled from 'styled-components';

const borderColor = '#4cd5b5';
const style = {
    Title: Styled.div`
        overflow:hidden;
        width: 100%;
        height: 420px;
        padding-top: 110px;
        margin-bottom: 50px;
        background: url('./assets/images/img_csc04.png') no-repeat center bottom;
        background-size: 400px auto;
        text-align: center;

        img{
            width: 100px;
            margin: 10px 0px;
        }
    `,
    Greet: Styled.div`
        font-size: 20px;
        text-align: left;
        h2 {
            font-size: 40px;
            margin-bottom: 30px;
            img {    
                width: 40px;
                margin: -6px 10px 0px 0px;
            }
        }
        .txt_intro{
            padding-bottom: 30px;
            border-bottom: 2px solid ${borderColor};
            font-size: 30px;
            img {    
                width: 63px;
                margin: -18px 0px 0px 14px;
            }
        }
    `,
};

export default style;
