import Styled from 'styled-components';
const style = {
    Navi: Styled.div`
        position: absolute;
        top: 0px;
        padding: 4px;

        h1 {
            padding: 2px 0 0 40px;
            margin: 10px 0 30px;
            font-size: 50px;
            font-weight: 400;
            cursor: default;
        }

        ul {
            font-size: 26px;
            li{
                position: relative;
                height: 34px;
                border-radius: 4px;
                padding: 2px 10px 7px 55px;
                margin-top: 20px;
                font-weight: 400;
                cursor: pointer;
                &.profile {
                    background: url('./assets/images/apple_notes.png') no-repeat 14px center;
                    background-size: 24px auto;
                    img {
                        display: none;
                        position: absolute;
                        top: -9px;
                        left: 124px;
                        width: 34px;
                        transform: rotate(11deg);
                    }
                }
                &.skill {
                    background: url('./assets/images/fantasy.png') no-repeat 14px center;
                    background-size: 24px auto;
                    &:hover {
                        padding-left: 70px;
                    }
                    img {
                        display: none;
                        position: absolute;
                        top: -16px;
                        left: 16px;
                        width: 40px;
                        transform: rotate(42deg);
                    }
                }
                &.career {
                    background: url('./assets/images/pokeball.png') no-repeat 14px 7px;
                    background-size: 24px auto;
                    &:hover {
                        background-image: url('./assets/images/open-pokeball.png');
                        background-position: 11px 3px;
                        background-size: 30px auto;
                        padding-left: 76px;
                    }
                    img {
                        display: none;
                        position: absolute;
                        top: 20px;
                        left: 28px;
                        width: 40px;
                    }
                }
                &.project {
                    background: url('./assets/images/github.png') no-repeat 14px center;
                    background-size: 24px auto;
                    &:hover {
                        background-image: url('./assets/images/code-fork.png');
                        background-position: 15px 2px;
                        background-size: 30px auto;
                    }
                }
                &.contact {
                    background: url('./assets/images/cell-phone.png') no-repeat 14px center;
                    background-size: 24px auto;
                    &:hover {
                        background: url('./assets/images/console.png') no-repeat 12px 6px;
                        background-size: 26px auto;
                    }
                }
                &:hover {
                    background-color: #13d1a440;
                    img {
                        display: block;
                    }
                }
            }
        }
    `,
};

export default style;
