import $ from 'jquery';
import { createContext, useContext, useEffect, useState } from 'react';
import Career from './components/Career';
import Contact from './components/Contact';
import Freelancer from './components/Freelancer';
import Header from './components/Header';
import Navi from './components/Navi';
import Profile from './components/Profile';
import Project from './components/Project';
import { LayoutContextStore } from './stores/LayoutContext';
import Styled from './styled/Index.style';

// 여기서 설정해서 useContext 로 전역에 사용
const viewSize = {
  view8: 800,
  view12: 1200,
  view16: 1600,
};

let currentPosition;
let position;
const naviScroll = () => {
  position = $(window).scrollTop();
  $('#navi')
    .stop()
    .animate({ top: position + currentPosition + 'px' }, 1000);
};

export const SetViewContext = createContext();
export const SetLinkOpen = createContext();
export const SetViewContact = createContext();
const App = () => {
  const [viewStore, setViewStore] = useState(0);
  const [viewBtnTop, setViewBtnTop] = useState(false);
  const [viewContact, setViewContact] = useState(false);
  const [viewMobile, setViewMobile] = useState(false);
  const [btnTop, setBtnTop] = useState(false);
  const sizeList = useContext(LayoutContextStore); // LayoutContext.js

  const linkOpen = (url) => {
    const win = window.open(url, '_blank');
  };
  useEffect(() => {
    const offset = $(`#${viewStore}`).offset();
    $('html').animate({ scrollTop: offset?.top - 500 }, 1000);
  }, [viewStore]);
  useEffect(() => {
    sizeList.setSizelist(viewSize);

    currentPosition = parseInt($('#navi').css('top'));
    $(document).ready(() => {
      naviScroll();
    });
    setViewBtnTop($(document).scrollTop() > 500);
    $(window).scroll(() => {
      naviScroll();
      setViewBtnTop($(document).scrollTop() > 500);
    });
    setViewMobile(window.innerWidth <= 1023);
    $(window).resize(() => {
      setViewMobile(window.innerWidth <= 1023);
    });
  }, [sizeList]);
  return (
    <Styled.Wrap>
      <SetViewContact.Provider value={{ viewContact, setViewContact }}>
        <Styled.Section className={viewMobile ? 'mobile' : ''}>
          <SetViewContext.Provider value={{ viewStore, setViewStore }}>
            <Styled.Navi>
              <Navi />
            </Styled.Navi>
          </SetViewContext.Provider>
          <SetLinkOpen.Provider value={{ linkOpen }}>
            <Styled.ContentsWrap>
              <Header />
              <Profile />
              <Career />
              <Freelancer />
              <Project />
            </Styled.ContentsWrap>
          </SetLinkOpen.Provider>
        </Styled.Section>
        {viewContact ? <Contact /> : undefined}
      </SetViewContact.Provider>
      {/* {viewMobile ? <Preparing /> : undefined} */}
      {viewBtnTop ? (
        <button
          className="btn_top"
          onClick={() => {
            $('html').animate({ scrollTop: 0 }, 1000);
          }}
        />
      ) : undefined}
    </Styled.Wrap>
  );
};

export default App;
