import Styled from 'styled-components';
const maxWidth = `1300px`;
const backColor = '#cfffdd';
const style = {
    Wrap: Styled.div`
        width: 100%;
        height: 100%;
        .btn_top {
            position: fixed;
            bottom: 30px;
            right: 30px;
            width: 80px;
            height: 80px;
            background: ${backColor} url('./assets/images/double-up.png') no-repeat center center;
            background-size: 30px auto;
            border: 2px solid #489987;
            border-radius: 100%;
            z-index: 5;
        }
    `,
    Section: Styled.div`
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        width: 100%;
        &.mobile {
            overflow-x: hidden;
            padding: 0 20px;
            /* filter: blur(10px);
            -webkit-filter: blur(10px); */
        }
    `,
    Navi: Styled.div`
        position: relative;
        width: 326px;
        background: ${backColor};
        @media screen and (max-width: ${maxWidth}) {
            display: none;
        }
    `,
    ContentsWrap: Styled.div`
        width: calc(100% - 326px);
        background: #26c39e;
        padding-bottom: 40px;
        text-align: center;

        & > * {
            max-width: 800px;
            margin: 0 auto;
        }
        @media screen and (max-width: ${maxWidth}) {
            width: 100%;
        }
    `,
};

export default style;
