import Styled from 'styled-components';

// const borderColor = '#4cd5b5';
const style = {
    Contact: Styled.div`
        display: flex;
        justify-content: center;
        align-items: center;
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.8);
        font-family: 'Nanum Gothic', '맑은 고딕','Malgun Gothic';
        z-index: 2;
        .center{
            position: relative;
            background: #0c0c0c;
            width: 900px;
            height: 500px;
            box-shadow: rgb(110 110 110) 0px 0px 1px 2px;
            color: #dfdfdf;
            .prompt {
                height: 30px;
                padding-left: 36px;
                background: #fff url('./assets/images/console.png') no-repeat 10px center;
                background-size: 18px auto;
                font-size: 14px;
                line-height: 30px;
                color: #333;
            }
            .btn_x {
                position: absolute;
                top: 0;
                right: 0px;
                width: 34px;
                height: 30px;
                background: #fff url('./assets/images/x.png') no-repeat center center;
                background-size: 20px auto;
                border: 0 none;
                &:hover {
                    background-color: #dfdfdf;
                }
            }
            ul {
                padding: 10px;
                li {
                    font-size: 30px;
                    line-height: 50px;
                    &.link {
                        cursor: pointer;
                    }
                    span {
                        display: inline-block;                    
                        width: 20px;
                        height: 7px;
                        margin-bottom: -10px;
                        background: #dfdfdf;
                        
                        animation-name: flash;
                        animation-duration: 1s;
                        animation-iteration-count: infinite;
                    }
                    @keyframes flash {
                        0%   {opacity: 1}
                        50% {opacity: 0}
                    }
                }
            }
        }
    `,
};

export default style;
