import Styled from 'styled-components';
const borderColor = '#4cd5b5';
const gitColor = '#1f83ff';
const style = {
    Career: Styled.div`
        padding-bottom: 40px;
        border-bottom: 2px solid ${borderColor};
        text-align: left;
        h2 {
            margin:30px 0;
            font-size: 40px;
            img {
                width: 55px;
                margin: -12px 0px 0px 17px;
            }
        }
        h3 {
            margin-bottom: 20px;
            font-size: 30px;
            &.free {
                margin-top: 20px;
            }
        }
        .career_list {
            position: relative;
            width: 100%;
            background: #fff;
            border-collapse: collapse;
            font-family: 'Nanum Gothic', '맑은 고딕','Malgun Gothic';
            font-size: 18px;
            text-align: center;
            vertical-align: middle;
            cursor: default;
            tr {
                th {
                    height: 30px;
                    border: 1px solid #dfdfdf;
                    font-size: 14px;
                    font-weight: 400;
                }
                td {
                    height: 40px;
                    &:nth-child(1) {
                        position: relative;
                        width:84px;
                        &:after {
                            content: '';
                            display: block;
                            position: absolute;       
                            top: 0px;
                            left: calc(50% - 1px);
                            width: 2px;
                            height: 100%;
                            background: ${gitColor};
                            z-index: 1;
                        }
                        &.no-line {
                            &:nth-child(1) {
                                &:after {
                                    display: none;
                                }
                            }
                        }
                    }
                    &.blank{
                        height: 15px;
                        &:after {
                            background: none;
                        }
                    }
                    &:nth-child(2) {
                        text-align: left;
                    }
                    &:nth-child(3) {
                        width: 180px;
                        font-size: 14px;
                    }
                    &:nth-child(4) {
                        width: 160px;
                        padding: 6px 0;
                        font-size: 16px;
                        line-height: 20px;
                    }
                    i {
                        display: block;
                        position: absolute;
                        top: calc(50% - 5px);
                        left: calc(50% - 5px);
                        width: 10px;
                        height: 10px;
                        background: ${gitColor};
                        border-radius: 100%;
                        z-index: 2;
                    }
                }
                &.company {
                    &.first {
                        td {
                            &:after {
                                top: -50%;
                            }
                        }
                    }
                    &.last {
                        td {
                            &:after {
                                top: 50%;
                            }
                        }
                    }
                }
                &.last {
                    td {
                        i {
                            top: calc(50% - 7px);
                            left: calc(50% - 7px);
                            width: 14px;
                            height: 14px;
                            background: #fff;
                            border: 2px solid ${gitColor};
                        }
                    }
                }    
                &.on {
                    background: #3399ff;
                    color: #fff;
                    td {
                        i {
                            box-shadow: rgb(255, 255, 255) 0px 0px 1px 2px;
                        }
                        border: 1px solid #3399ff;
                    }
                }
                &.work {
                    padding: 10px 0;
                    font-size: 14px;
                    text-align: left;
                    &.first {
                        td {
                            &:after {
                                background: #fff;
                            }
                        }
                    }
                    li {    
                        position: relative;
                        padding: 10px 0;
                        border-bottom: 1px solid #dfdfdf;   
                        color: #333;
                        &:last-child {
                            border-bottom: 0 none;
                        }
                        &.link {
                            /* text-decoration: underline; */
                            color: #333;
                            cursor: pointer;
                            img {
                                width: 22px;
                                margin-left: 6px;
                            }
                            &:hover {
                                color: rgb(51, 153, 255);
                            }
                        }
                    }
                }
            }
        }
    `,
};

export default style;
